// Belnap four-valued logic evaluator (sketch)
function not(v){ if(v==='T') return 'F'; if(v==='F') return 'T'; return v; }
function implies(a,b){ return or(not(a), b); }
function and(a,b){ /* truth table for ∧ */ }
